import paramiko
from paramiko.ssh_exception import SSHException

from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from paramiko import SSHClient

from taf.hw.rf_switch.exceptions import RfSwitchActionNotSupported, RfSwitchError, RfSwitchActionFailed


class RPI(RfSwitch):
    """Class for RPI RF Switch.

    Rpi RF Switch is a simple RPI board with IO expanders managed via I2C bus.
    Currently each expander has hardwired output, so port_out is not used.
    """

    BANK_MAPPING = {}
    BANK_OUTPUT_MAPPING = {}
    PIN_MAPPING = {}
    EXPANDER_MAPPING = {}

    def __init__(self, ip: str, username: str, password: str, port: int = 22) -> None:
        super().__init__()
        self.ip = ip
        self.port = port
        self.username = username
        self.password = password
        self._set_expander_mapping()

    def _set_bank_as_output(self, ic_address: str, bank: str) -> None:
        """Set bank A or B of given expander as output.

        :param ic_address: ic_address of given expander.
        :param bank: Which bank to set, either "A" or "B".
        """
        bank_hex = self.BANK_OUTPUT_MAPPING.get(bank)
        if bank_hex is None:
            raise RfSwitchError(f"Bank {bank} not supported.\n"
                                f"Bank should be one of: {self.BANK_OUTPUT_MAPPING.keys()}")
        command = f"{ic_address} {bank_hex} 0x00"
        self._send_i2cset_command(command)

    def _set_all_bank_outputs_low(self, ic_address: str, bank: str) -> None:
        """Set all outputs of given bank to low.

        :param ic_address: ic_address of given expander.
        :param bank: Which bank to set, either "A" or "B".
        """
        bank_hex = self.BANK_MAPPING.get(bank)
        if bank_hex is None:
            raise RfSwitchError(f"Bank {bank} not supported.\n"
                                f"Bank should be one of: {self.BANK_OUTPUT_MAPPING.keys()}")
        command = f"{ic_address} {bank_hex} 0x00"
        self._send_i2cset_command(command)

    def _set_output_high(self, ic_address: str, bank: str, pin: str) -> None:
        """Set one output of given bank to high.

        :param ic_address: ic_address of given expander.
        :param bank: Which bank to set, either "A" or "B".
        :param pin: Which pin to change, 0-7.
        """
        bank_hex = self.BANK_MAPPING.get(bank)
        pin_hex = self.PIN_MAPPING.get(pin)
        if bank_hex is None:
            raise RfSwitchError(f"Bank {bank} not supported.\n"
                                f"Bank should be one of: {self.BANK_OUTPUT_MAPPING.keys()}")
        if pin_hex is None:
            raise RfSwitchError(f"Pin {pin} not supported.\n"
                                f"Pin should be one of: {self.PIN_MAPPING.keys()}")
        command = f"{ic_address} {bank_hex} {pin_hex}"
        self._send_i2cset_command(command)

    def _send_i2cset_command(self, sub_command: str) -> None:
        """Send i2cset command.

        Command is in form: i2cset -y 1 sub_command.
        :param sub_command: string of "<ic_address> <bank> <state>", e.g. 0x20 0x00 0x00.
        """
        try:
            with SSHClient() as ssh:
                ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                ssh.connect(hostname=self.ip, port=self.port, username=self.username, password=self.password)
                ssh.exec_command(f"sudo i2cset -y 1 {sub_command}")
        except SSHException as exc:
            raise RfSwitchActionFailed("Failed to send i2cset command.") from exc

    def _send_i2cget_command(self, sub_command: str) -> str:
        """Send i2cget command.

        Command is in form: i2cget -y 1 sub_command.
        :param sub_command: string of "<ic_address> <bank>", e.g. 0x20 0x00.
        :return: Stdout from ssh command execution.
        """
        try:
            with SSHClient() as ssh:
                ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                ssh.connect(hostname=self.ip, port=self.port, username=self.username, password=self.password)
                stdin, stdout, stderr = ssh.exec_command(f"sudo i2cget -y 1 {sub_command}")
                return stdout.read().decode('utf-8')
        except SSHException as exc:
            raise RfSwitchActionFailed("Failed to send i2cget command.") from exc

    def _send_i2cdetect_command(self) -> str:
        """Send i2cdetect command.

        :return: Stdout from ssh command execution.
        """
        try:
            with SSHClient() as ssh:
                ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                ssh.connect(hostname=self.ip, port=self.port, username=self.username, password=self.password)
                stdin, stdout, stderr = ssh.exec_command("sudo i2cdetect -y 1")
                return stdout.read().decode('utf-8')
        except SSHException as exc:
            raise RfSwitchActionFailed("Failed to send i2cdetect command.") from exc

    def _set_expander_mapping(self) -> None:
        """Check which addresses do expanders have."""
        first_map = {
            "1": "0x20",
            "2": "0x21",
            "3": "0x22",
            "4": "0x23",
        }
        second_map = {
            "1": "0x24",
            "2": "0x25",
            "3": "0x26",
            "4": "0x27",
        }
        rsp = self._send_i2cdetect_command()
        is_first_set = all(val[2:] in rsp for val in first_map.values())
        is_second_set = all(val[2:] in rsp for val in second_map.values())
        if is_first_set and is_second_set:
            raise RfSwitchError(f"There are devices connected to all addresses between 20-27:\n{rsp}\n"
                                "Cannot decide where are the expanders.\n"
                                "Please plug one non-expander device to different address.")
        elif is_first_set:
            self.EXPANDER_MAPPING = first_map
        elif is_second_set:
            self.EXPANDER_MAPPING = second_map
        else:
            raise RfSwitchError("4 expanders should be connected to addresses 20-23 or 24-27."
                                f"Please see i2cdetect result:\n{rsp}")

    def connect_ports(self, port_in: str, port_out: str = "-1") -> None:
        """Set given port as input.

        :param port_in: Port to be set as input, given in form <Expander><Bank>:<Pin>, e.g. "1A:0"
        :param port_out: NOT USED. Abstract method defines port_out so it must be here.
                         Currently, each expander is connected to dedicated analyzer, so no ports out are to be set.
        """
        port_in_parts = port_in.split(":")
        expander, bank = port_in_parts[0][:]
        pin = port_in_parts[1]
        ic_address = self.EXPANDER_MAPPING.get(expander)
        if ic_address is None:
            raise RfSwitchError(f"Expander {expander} not supported.\n"
                                f"Expander should be one of: {self.EXPANDER_MAPPING.keys()}")
        self._set_bank_as_output(ic_address, bank)
        self._set_all_bank_outputs_low(ic_address, bank)
        self._set_output_high(ic_address, bank, pin)

    def disconnect_ports(self, port_in: str, port_out: str = "-1") -> None:
        """Set all ports low in given bank and expander.

        :param port_in: Port which bank and expander are to be set low,
                          given in form <Expander><Bank>:<Pin>, e.g. "1A:0" or "1A".
        :param port_out: NOT USED. Abstract method defines port_out so it must be here.
                         Currently, each expander is connected to dedicated analyzer, so no ports out are to be set.
        To achieve that, set related bank as output and set all ports low, as only one port can be connected at a time.
        """
        port_in_parts = port_in.split(":")
        expander, bank = port_in_parts[0][:]
        ic_address = self.EXPANDER_MAPPING.get(expander)
        if ic_address is None:
            raise RfSwitchError(f"Expander {expander} not supported.\n"
                                f"Expander should be one of: {self.EXPANDER_MAPPING.keys()}")
        self._set_bank_as_output(ic_address, bank)
        self._set_all_bank_outputs_low(ic_address, bank)

    def get_port_in_status(self, port_in):
        """Not implemented."""
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)

    def get_port_out_status(self, port_out):
        """Not implemented."""
        msg = "Action not implemented for this device, please contact library maintainers if it is needed."
        raise RfSwitchActionNotSupported(msg)

    def get_connected_ports(self) -> list[str]:
        """Get connected ports.

        :return: Return list of ports that are set high.
        """
        connected_ports = []
        for expander in self.EXPANDER_MAPPING.keys():
            for bank in self.BANK_MAPPING.keys():
                rsp = self._send_i2cget_command(
                    f"{self.EXPANDER_MAPPING.get(str(expander))} {self.BANK_MAPPING.get(bank)}"
                )
                pin = rsp[2:4]
                if rsp[2:4] != "00":
                    connected_ports.append(
                        f"{expander}{bank}:"
                        f"{[i for i in self.PIN_MAPPING if self.PIN_MAPPING.get(i) == '0x'+pin][0]}"
                    )
        return connected_ports


class MCP23017(RPI):
    """This class represents IC I/O expander type.

    While not exactly a subtype of RPI, all expanders connected to one RPI should be of the same type,
    so it is feasible to make it a subclass of RPI.
    """
    BANK_MAPPING = {
        "A": "0x14",
        "B": "0x15"
    }
    BANK_OUTPUT_MAPPING = {
        "A": "0x00",
        "B": "0x01"
    }
    PIN_MAPPING = {
        "0": "0x01",
        "1": "0x02",
        "2": "0x04",
        "3": "0x08",
        "4": "0x10",
        "5": "0x20",
        "6": "0x40",
        "7": "0x80",
    }
